import rclpy
from rclpy.node import Node
from std_msgs.msg import Header
from std_msgs.msg import Float64MultiArray
import sys
import time
import numpy as np

class LeftArmJointspaceCommander(Node):
    def __init__(self):
        super().__init__('left_arm_jointspace_commander')
        # 发布/jointspace_commands_L
        self.joint_cmd_pub = self.create_publisher(Float64MultiArray, '/jointspace_commands_L', 10)
        self.timer = self.create_timer(0.01, self.publish_joint_commands)
        self.time_start = self.get_clock().now().nanoseconds * 1e-9
        self.lower_limit = [-2.96, -0.262, -2.96, -2.61, -2.96, -0.785, -1.3]
        self.upper_limit = [2.96, 2.616, 2.96, 0.261, 2.96, 1.05, 1.65]
        self.mid = [(self.lower_limit[i] + self.upper_limit[i]) / 2 for i in range(7)]
        self.amplitude = [(self.upper_limit[i] - self.lower_limit[i]) / 2 for i in range(7)]
        
        self.T = 10.0
        self.lisaro_factor = [1.0, 
                            np.sqrt(2)/1.4, 
                            np.sqrt(3)/1.7, 
                            np.sqrt(5)/2.0, 
                            np.sqrt(6)/2.3, 
                            np.sqrt(7)/2.6, 
                            np.sqrt(11)/2.9]
        print(self.lisaro_factor)

    def publish_joint_commands(self):
        elapsed = self.get_clock().now().nanoseconds * 1e-9 - self.time_start  # 获取运行时间(秒)
        msg = Float64MultiArray()
        msg.data = [0.0] * 7
        msg.data[0] = self.mid[0] + self.amplitude[0] * np.sin(2 * np.pi * elapsed / self.T * self.lisaro_factor[0])
        msg.data[1] = self.mid[1] + self.amplitude[1] * np.sin(2 * np.pi * elapsed / self.T * self.lisaro_factor[1])
        msg.data[2] = self.mid[2] + self.amplitude[2] * np.sin(2 * np.pi * elapsed / self.T * self.lisaro_factor[2])
        msg.data[3] = self.mid[3] + self.amplitude[3] * np.sin(2 * np.pi * elapsed / self.T * self.lisaro_factor[3])
        msg.data[4] = self.mid[4] + self.amplitude[4] * np.sin(2 * np.pi * elapsed / self.T * self.lisaro_factor[4])
        msg.data[5] = self.mid[5] + self.amplitude[5] * np.sin(2 * np.pi * elapsed / self.T * self.lisaro_factor[5])
        msg.data[6] = self.mid[6] + self.amplitude[6] * np.sin(2 * np.pi * elapsed / self.T * self.lisaro_factor[6])
        self.joint_cmd_pub.publish(msg)
        self.get_logger().info(f'时间：{elapsed}, 发布/jointspace_commands_L: {msg.data}')

def main(args=None):
    rclpy.init(args=args)
    node = LeftArmJointspaceCommander()
    print("正在向/jointspace_commands_L周期性发送左臂关节角度...")
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        rclpy.shutdown()

if __name__ == '__main__':
    main()
